def good_wrong_choices(case, field, k=3):
    # Real, clinically meaningful distractors from the same rotation, never fabricated drug names or mechanisms.
    # Prefer overlap where possible but exclude exact matches and avoid repeating an answer.
    ans=case[field]
    pool=[other[field] for other in records if other['id']!=case['id'] and other['specialty']==case['specialty'] and other[field]!=ans]
    normalized=lambda s:set(re.findall(r'[a-z]{4,}',s.lower()))-{'with','after','into','when','from','that','their','this','does','than','they','have','some','would','through','where','about','those','which','include','patient','because','should'}
    words=normalized(ans)
    rnd=random.Random(int(case['id'][2:])+sum(ord(x) for x in field+case['id']))
    rnd.shuffle(pool)
    ranked=sorted(pool,key=lambda x:len(words&normalized(x))/max(1,len(words|normalized(x))),reverse=True)
    picked=[]
    for candidate in ranked:
        if candidate not in picked and candidate!=ans:picked.append(candidate)
        if len(picked)==k:break
    assert len(picked)==k
    return picked

PROMPTS={
 'diagnosis':[
  'What is the best working diagnosis or clinical problem to prioritize from this presentation?',
  'What diagnosis best unifies the history and examination, while keeping emergencies in mind?',
  'What is the most likely clinical syndrome on your initial differential?',
 ],
 'test':[
  'What additional test or finding would most directly support this diagnosis or change the workup?',
  'Which investigation or diagnostic discriminator is most useful at this stage?',
  'What is the most informative next piece of diagnostic evidence for this presentation?',
 ],
 'phys':[
  'What pathophysiologic mechanism best accounts for this presentation?',
  'Your attending asks you to explain the underlying physiology. Which explanation fits best?',
  'Which cellular, anatomic, or physiologic mechanism most directly generates these findings?',
 ],
 'treat':[
  'With the likely diagnosis established, which management approach best addresses the patient’s current needs?',
  'What is the most appropriate treatment or clinical action now?',
  'What management plan is most consistent with the underlying disease and immediate risks?',
 ],
 'comp':[
  'Which important complication or safety issue deserves attention as the case evolves?',
  'Which potential adverse outcome would your attending most want you to anticipate here?',
  'What dangerous evolution of this problem should guide monitoring and contingency planning?',
 ],
 'advanced':[
  'A senior attending challenges your plan. Which nuanced statement is most accurate for this particular case?',
  'Which higher-level consideration should change how you interpret or manage this case?',
  'In a deeper clinical discussion, which caveat is the most defensible for this patient?',
 ],
}

def question(c,field,i):
 rnd=random.Random(c['id']+field)
 prompt=rnd.choice(PROMPTS[field]); correct=c[field]
 wrong=c['ddx'] if field=='diagnosis' else good_wrong_choices(c,field)
 exp={
  'diagnosis':f"The presentation most strongly supports {correct}. Near misses include {c['ddx'][0]} and {c['ddx'][1]}, but the full clinical pattern should determine the working diagnosis.",
  'test':f"For this presentation the most discriminating evaluation is: {correct}. Use the result in context rather than treating a single laboratory or imaging finding in isolation.",
  'phys':f"The relevant mechanism is: {correct}. This explains the major features of the vignette and informs treatment selection.",
  'treat':f"A sound clinical strategy is: {correct}. The exact plan must still account for stability, contraindications, risk factors and local protocols.",
  'comp':f"The specific risk to recognize is: {correct}. Anticipating the complication supports earlier escalation or more appropriate follow-up.",
  'advanced':f"Advanced clinical teaching point: {correct}. This modifies a simplistic algorithm and is especially important when presentations are atypical or unstable.",
 }[field]
 hint={
  'diagnosis':f"Compare the presentation with {c['ddx'][0]} and identify the most distinctive pattern.",
  'test':'Which test or finding meaningfully separates the most likely diagnosis from its nearest mimics?',
  'phys':'Identify the tissue, pathway, or molecular process causing the hallmark clinical findings.',
  'treat':'Prioritize any immediate threats, then treat the mechanism rather than only a symptom.',
  'comp':'Think about the consequence of progression, treatment delay, or a treatment-related adverse event.',
  'advanced':'What is the exception to the common rule that an attending would expect you to remember?',
 }[field]
 probe={
  'test':f"What alternative clinical problem must still be excluded if the test is equivocal?",
  'phys':f"How might this mechanism change the patient’s examination or treatment response?",
  'treat':f"What would make this plan unsafe or require escalation?",
  'comp':f"What finding would tell you that this complication is developing?",
  'advanced':f"How would you explain this nuance to another student in two sentences?",
 }.get(field,'')
 probe_answer={
  'test':f"The nearest competing diagnosis is {c['ddx'][0]}; consider the full risk and symptom pattern.",
  'phys':f"The defining disease mechanism in this case: {c['phys']}",
  'treat':f"Treatment and safety must both be addressed: {c['treat']}. Monitor for: {c['comp']}.",
  'comp':f"Specific warning to anticipate: {c['comp']}.",
  'advanced':f"Key nuance: {c['advanced']}",
 }.get(field,'')
 update = f"Further evaluation supports the suspected process: {c['test']}." if i==1 else ''
 return dict(id=f"{c['id']}-Q{i+1}",stage=STAGES[i],depth=i+1,prompt=prompt,
             options=[correct,*wrong],correct=0,explanation=exp,hint=hint,
             probe=probe,probeAnswer=probe_answer,update=update)

created=[]
for c in records:
 name, url=DIRECT.get(c['id'],('NCBI Bookshelf — clinical topic search (select a reference)',
        'https://www.ncbi.nlm.nih.gov/books/?term='+urllib.parse.quote(c['diagnosis']+' diagnosis management')))
 case=dict(id=c['id'],specialty=c['specialty'],difficulty=c['difficulty'],title=c['title'],scene=c['scene'],vitals=c['vitals'],
      questions=[question(c,field,i) for i,field in enumerate(['diagnosis','test','phys','treat','comp','advanced'])],
      stable='The patient is reassessed and improves following an appropriate, monitored plan.',
      unstable=f"A new concern requires urgent reassessment: {c['comp']}.",
      sources=[{'label':name,'url':url}],tags=[c['difficulty'],'New case'])
 created.append(case)

all_cases=legacy+created
ids=[c['id'] for c in all_cases]
assert len(all_cases)==108 and len(set(ids))==108
assert collections.Counter(c['specialty'] for c in all_cases)=={v:12 for v in SPEC.values()}
for c in all_cases:
 assert c['difficulty'] in ('Foundations','Clinical','Advanced'),c['id']
 assert len(c['questions'])==6
 for i,q in enumerate(c['questions']):
  assert q['id']==f"{c['id']}-Q{i+1}"
  assert len(q['options'])==4 and len(set(q['options']))==4,c['id']
  assert q['correct']==0 and q['stage']==STAGES[i]
  assert q['explanation'] and q['hint']
 assert c['sources'] and all(x['url'].startswith('https://') for x in c['sources'])

(ROOT/'cases.json').write_text(json.dumps(all_cases,ensure_ascii=False,indent=2)+'\n')
(ROOT/'cases.js').write_text('window.ATTENDING_CASES='+json.dumps(all_cases,ensure_ascii=False,separators=(',',':'))+';\n')
print('Created',len(created),'additional original cases; total',len(all_cases))
print('Difficulty counts:',collections.Counter(c['difficulty'] for c in all_cases))
print('Specialties:',collections.Counter(c['specialty'] for c in all_cases))
print('Questions',sum(len(c['questions']) for c in all_cases))
